/// A 10-second rotating attendance QR token for an event (or session, once
/// Slice 4 adds those) — generated by `start_event_qr`. Mirrors
/// `matches`' `MeetingSession`, except this one keeps getting re-issued via
/// `EventQrController`'s periodic timer instead of living for one claim.
class EventQrToken {
  const EventQrToken({required this.token, required this.expiresAt});

  final String token;
  final DateTime expiresAt;

  /// Matches the `c2c:meeting:` prefix convention used for 1:1 meeting QRs.
  String get qrValue => 'c2c:event:$token';

  bool get isExpired => DateTime.now().isAfter(expiresAt);
}
